import settings from './assets/settings.svg';

const Menu = ({ onClick }) => {
  return (
    <button className="colo" onClick={onClick}>
      <img
        className="hover:bg-opacity-30 transition-all"
        id="settings"
        src={settings}
        alt="Settings Icon"
      />
    </button>
  );
};

export default Menu;
